html:
{%- set d = get_ticket_print_data(doc.name) -%}
{%- set h = d.header -%}
{%- macro fmt(v) -%}{{ '{:,.2f}'.format((v or 0)|float) }}{%- endmacro -%}
{%- macro fmtq(v) -%}
  {%- set n = (v or 0)|float -%}
  {%- if n == n|int -%}{{ n|int }}{%- else -%}{{ '{:g}'.format(n) }}{%- endif -%}
{%- endmacro -%}

<style>
  .jt { font-family: Arial, Helvetica, sans-serif; font-size: 11px; color: #222; }
  .jt-top { width:100%; border-collapse:collapse; margin-bottom:6px; }
  .jt-top td { vertical-align:top; }
  .jt-co { font-size:12px; font-weight:bold; }
  .jt-title { text-align:center; font-size:13px; font-weight:bold; }
  .jt-name { text-align:right; font-family:monospace; font-size:12px; font-weight:bold; }
  .info { width:100%; border-collapse:collapse; margin-bottom:8px; border:1px solid #333; }
  .info td { padding:3px 6px; border:1px solid #ccc; font-size:10.5px; vertical-align:top; }
  .info td.k { font-weight:bold; white-space:nowrap; width:12%; background:#f5f5f5; }
  .fin { margin:4px 0; font-size:10.5px; }
  .tbl { width:100%; border-collapse:collapse; margin:8px 0; font-size:10px; }
  .tbl th { background:#2b2b2b; color:#fff; padding:4px 5px; border:1px solid #555; text-align:center; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
  .tbl td { padding:3px 5px; border:1px solid #ddd; text-align:center; }
  .tbl td.l { text-align:left; }
  .mat th { background:#444; }
  .sec-lbl { font-weight:bold; font-size:10.5px; margin:8px 0 3px; }
  .sign { width:100%; border-collapse:collapse; margin-top:22px; }
  .sign td { text-align:center; font-size:10px; border-top:1px solid #333; padding-top:4px; width:20%; }
  .sign .nm { border:0; padding-bottom:18px; font-weight:bold; }
</style>

<div class="jt">
  <table class="jt-top">
    <tr>
      <td style="width:33%">
        {% if d.logo %}<img src="{{ d.logo }}" style="height:42px;display:block;margin-bottom:2px">{% endif %}
        <div class="jt-co">Savinda Graphic Systems (Pvt) Ltd.</div>
      </td>
      <td style="width:40%"><div class="jt-title">{{ 'Flexo' if d.is_flexo else 'Offset' }} Job Ticket ( No FSC )</div></td>
      <td style="width:27%"><div class="jt-name">{{ doc.name }}</div></td>
    </tr>
  </table>

  <table class="info">
    <tr>
      <td class="k">Job Title</td><td colspan="3">{{ h.job_title }}</td>
      <td class="k">Job No</td><td>{{ doc.name }}</td>
    </tr>
    <tr>
      <td class="k">Customer</td><td colspan="3">{{ h.customer }}</td>
      <td class="k">Job Date</td><td>{{ h.job_date }}</td>
    </tr>
    <tr>
      <td class="k">Art. No</td><td>{{ h.art_no }}</td>
      <td class="k">Art. Ver</td><td>{{ h.art_version }}</td>
      <td class="k">Req. Date</td><td>{{ h.req_date }}</td>
    </tr>
    <tr>
      <td class="k">PO No</td><td>{{ h.po_no }}</td>
      <td class="k">Colors</td><td>{{ h.colors }}</td>
      <td class="k">Quote No</td><td>{{ h.quote_no }}</td>
    </tr>
    <tr>
      <td class="k">Job Board</td><td colspan="3">{{ h.job_board }}</td>
      <td class="k">Color Ref.</td><td>{{ h.color_ref }}</td>
    </tr>
    <tr>
      <td class="k">Printing M/C</td><td>{{ h.printing_machine }}</td>
      <td class="k">Pricing</td><td>{{ 'Flexo' if d.is_flexo else 'Offset' }}</td>
      <td class="k">NPD Ref</td><td>{{ h.npd_request }}</td>
    </tr>
  </table>

  <div class="fin"><b>Finishings :</b> {{ h.finishings }}</div>
  <div class="fin"><b>Remarks :</b> {{ h.remarks }}</div>

  <table class="tbl">
    <thead>
      <tr>
        <th class="l" style="width:28%">Description</th>
        <th>Qty</th><th>Product Code</th><th>Batch/Lot</th>
        {% if d.is_flexo %}
        <th>Reel Length (m)</th><th>Reel Width (mm)</th><th>Reel Area (sq_m)</th><th>Slit Width (mm)</th>
        {% else %}
        <th>Full Sheets</th><th>Cut Sheets</th><th>F.Sheet Size</th><th>C.Sheet Size</th><th>Cuts</th><th>Ups</th>
        {% endif %}
      </tr>
    </thead>
    <tbody>
      {% for r in d.lines %}
      <tr>
        <td class="l">{{ r.description }}</td>
        <td>{{ fmtq(r.qty) }}</td><td>{{ r.product_code }}</td><td>{{ r.batch_no }}</td>
        {% if d.is_flexo %}
        <td>{{ fmtq(r.reel_length) }}</td><td>{{ fmtq(r.reel_width) }}</td><td>{{ fmtq(r.reel_area) }}</td><td>{{ r.slit_width }}</td>
        {% else %}
        <td>{{ fmtq(r.full_sheets) }}</td><td>{{ fmtq(r.cut_sheets) }}</td><td>{{ r.full_sheet_size }}</td><td>{{ r.cut_sheet_size }}</td><td>{{ r.cuts }}</td><td>{{ r.ups }}</td>
        {% endif %}
      </tr>
      {% endfor %}
    </tbody>
  </table>

  <div class="sec-lbl">BOM Materials (Non-Board Items)</div>
  <table class="tbl mat">
    <thead><tr><th class="l" style="width:60%">Item Name</th><th>Unit</th><th>Quantity</th><th>Wastage Qty</th></tr></thead>
    <tbody>
      {% for m in d.materials %}
      <tr><td class="l">{{ m.item_name }}</td><td>{{ m.uom }}</td><td>{{ fmtq(m.quantity) }}</td><td>{{ fmtq(m.wastage_qty) }}</td></tr>
      {% endfor %}
      {% if not d.materials %}<tr><td class="l">&nbsp;</td><td></td><td></td><td></td></tr>{% endif %}
    </tbody>
  </table>

  <table class="sign">
    <tr>{% for a in d.approvals %}<td class="nm">{{ a.by }}</td>{% endfor %}</tr>
    <tr>{% for a in d.approvals %}<td>{{ a.label }}<br><span style="color:#666">{{ a.on or '' }}</span></td>{% endfor %}</tr>
  </table>
</div>

css:
.breakdown-cell {
    padding: 2px 4px !important;
    vertical-align: top;
    text-align: center;
}

.breakdown-value {
    min-height: 18px;
    line-height: 18px;
    white-space: nowrap;
}

html:
{%- set d = get_npd_print_data(doc.name) -%}
{%- macro fmtq(v) -%}
  {%- set n = (v or 0)|float -%}
  {%- if n == n|int -%}{{ n|int }}{%- else -%}{{ '{:g}'.format(n) }}{%- endif -%}
{%- endmacro -%}

<style>
  .npd { font-family: Arial, Helvetica, sans-serif; font-size: 11px; color: #222; }
  .npd-hdr { text-align:center; margin-bottom:6px; }
  .npd-co { font-size:12px; font-weight:bold; }
  .npd-title { font-size:13px; font-weight:bold; }
  .meta { width:100%; border-collapse:collapse; margin-bottom:8px; }
  .meta td { padding:2px 6px; font-size:10.5px; vertical-align:top; }
  .meta td.k { font-weight:bold; white-space:nowrap; }
  .kv { font-size:10.5px; margin:2px 0; }
  .kv b { display:inline-block; min-width:130px; }
  .tbl { width:100%; border-collapse:collapse; margin:8px 0; font-size:10px; }
  .tbl th { background:#2b2b2b; color:#fff; padding:4px 5px; border:1px solid #555; text-align:center; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
  .tbl td { padding:3px 5px; border:1px solid #ddd; text-align:center; }
  .tbl td.l { text-align:left; }
  .sec-lbl { font-weight:bold; font-size:10.5px; margin:8px 0 3px; }
  .footer-tbl { width:100%; border-collapse:collapse; margin-top:8px; font-size:10.5px; }
  .footer-tbl td { padding:2px 6px; }
  .footer-tbl td.k { font-weight:bold; white-space:nowrap; }
  .sign { width:60%; border-collapse:collapse; margin-top:26px; }
  .sign td { text-align:center; font-size:10px; border-top:1px solid #333; padding-top:4px; width:50%; }
  .sign .nm { border:0; padding-bottom:18px; font-weight:bold; }
</style>

<div class="npd">
  <div class="npd-hdr">
    {% if d.logo %}<img src="{{ d.logo }}" style="height:42px;display:block;margin:0 auto 2px">{% endif %}
    <div class="npd-co">Savinda Graphic Systems (Pvt) Ltd.</div>
    <div class="npd-title">{{ 'Flexo' if d.is_flexo else 'Offset' }} NPD Job Ticket ( No FSC ) ( NEW )</div>
  </div>

  <table class="meta">
    <tr>
      <td class="k">NPD No</td><td>: {{ doc.name }}</td>
      <td class="k">INQ No.</td><td>: {{ doc.inquiry or '' }}</td>
    </tr>
    <tr>
      <td class="k">NPD Date</td><td>: {{ doc.npd_date }}</td>
      <td class="k">Quote No</td><td>: {{ doc.quote_no or '' }}</td>
    </tr>
    <tr>
      <td class="k">Customer</td><td>: {{ doc.customer_name or '' }}</td>
      <td class="k">Sales p.</td><td>: {{ doc.sales_person or '' }}</td>
    </tr>
    <tr>
      <td class="k">Attention To</td><td>: {{ doc.attention_to or '' }}</td>
      <td class="k">Req. Sample Qty</td><td>: {{ doc.sample_qty or 0 }}</td>
    </tr>
  </table>

  <div class="kv"><b>Job Title</b>: {{ doc.job_title or '' }}</div>
  <div class="kv"><b>Material</b>: {{ doc.material or '' }}</div>
  <div class="kv"><b>Size</b>: {{ doc.size or '' }}</div>
  <div class="kv"><b>Color reference</b>: {{ doc.color_ref or '' }}</div>
  <div class="kv"><b>Colors</b>: {{ doc.colors or 0 }}</div>
  <div class="kv"><b>Finishings</b>: {{ doc.finishings or '' }}</div>
  <div class="kv"><b>Remarks</b>: {{ doc.remarks or '' }}</div>

  <table class="tbl">
    <thead>
      <tr>
        <th>#</th><th class="l" style="width:30%">Description</th><th>Size</th><th>Quantity</th>
        {% if d.is_flexo %}
        <th>Reel Area (sq_m)</th><th>Full Sheets</th><th>Cut Sheets</th><th>Ups</th><th>Cuts</th>
        {% else %}
        <th>Full Sheet Size</th><th>Cut Sheet Size</th><th>Full Sheets</th><th>Cut Sheets</th><th>Ups</th><th>Cuts</th>
        {% endif %}
      </tr>
    </thead>
    <tbody>
      {% for r in d.lines %}
      <tr>
        <td>{{ loop.index }}</td><td class="l">{{ r.item_name }}</td><td>{{ r.size }}</td><td>{{ fmtq(r.qty) }}</td>
        {% if d.is_flexo %}
        <td>{{ fmtq(r.reel_area) }}</td><td>{{ fmtq(r.full_sheets) }}</td><td>{{ fmtq(r.cut_sheets) }}</td><td>{{ r.ups }}</td><td>{{ r.cuts }}</td>
        {% else %}
        <td>{{ r.full_sheet_size }}</td><td>{{ r.cut_sheet_size }}</td><td>{{ fmtq(r.full_sheets) }}</td><td>{{ fmtq(r.cut_sheets) }}</td><td>{{ r.ups }}</td><td>{{ r.cuts }}</td>
        {% endif %}
      </tr>
      {% endfor %}
    </tbody>
  </table>

  {% if d.is_flexo %}
  <div class="sec-lbl">Product Development Details</div>
  <table class="tbl">
    <thead>
      <tr>
        <th>#</th><th class="l" style="width:24%">Description</th><th>Reel Length</th><th>Reel Width</th><th>Slit Width</th>
        <th>Repeat teeth</th><th>Repeat Ups</th><th>Repeat Gaps</th><th>Across Ups</th><th>Across Gaps</th><th>Across Material Width</th>
      </tr>
    </thead>
    <tbody>
      {% for r in d.lines %}
      <tr>
        <td>{{ loop.index }}</td><td class="l">{{ r.item_name }}</td><td>{{ fmtq(r.reel_length) }}</td><td>{{ fmtq(r.reel_width) }}</td><td>{{ r.slit_width }}</td>
        <td>{{ r.repeat_teeth }}</td><td>{{ r.repeat_ups }}</td><td>{{ r.repeat_gaps }}</td><td>{{ r.across_ups }}</td><td>{{ r.across_gaps }}</td><td>{{ r.material_width }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>
  {% endif %}

  {% if d.materials %}
  <div class="sec-lbl">BOM Materials</div>
  <table class="tbl mat">
    <thead><tr><th class="l" style="width:60%">Item Name</th><th>Unit</th><th>Quantity</th></tr></thead>
    <tbody>
      {% for m in d.materials %}
      <tr><td class="l">{{ m.item_name }}</td><td>{{ m.uom }}</td><td>{{ fmtq(m.quantity) }}</td></tr>
      {% endfor %}
    </tbody>
  </table>
  {% endif %}

  <table class="footer-tbl">
    <tr>
      <td class="k">Winding Direction</td><td>: {{ doc.winding_direction or '' }}</td>
      <td class="k">No of inner pages</td><td>: {{ doc.no_of_inner_pages or 0 }}</td>
    </tr>
    <tr>
      <td class="k">No of ups per reel</td><td>: {{ doc.no_of_ups_per_reel or 0 }}</td>
      <td class="k">No of cover pages</td><td>: {{ doc.no_of_cover_pages or 0 }}</td>
    </tr>
    <tr>
      <td class="k">No of labels per reel</td><td>: {{ doc.no_of_labels_per_reel or 0 }}</td>
      <td class="k">Core size</td><td>: {{ doc.core_size or 0 }}</td>
    </tr>
  </table>

  <table class="sign">
    <tr>
      <td class="nm">{{ d.created_by }}</td>
      <td class="nm">{{ d.approved_by or 'Pending' }}</td>
    </tr>
    <tr>
      <td>Created by<br><span style="color:#666">{{ d.created_on or '' }}</span></td>
      <td>Approved by<br><span style="color:#666">{{ d.approved_on or '' }}</span></td>
    </tr>
  </table>
</div>

{% set sp_name = frappe.db.get_value('User', doc.sales_person, 'full_name') or doc.sales_person or '' %}
{% set sp_desig = frappe.db.get_value('User', doc.sales_person, 'designation') or '' %}
{% set ns_i = namespace(names=[]) %}
{% for row in doc.items %}{% if row.item_name and row.item_name not in ns_i.names %}{% set ns_i.names = ns_i.names + [row.item_name] %}{% endif %}{% endfor %}
<style>
body{margin:0;padding:0}
