script:
frappe.ui.form.on('Opportunity', {
    refresh(frm) {
        if (window.__savret_bound) return;
        window.__savret_bound = true;

        document.addEventListener('click', function (e) {
            const el = e.target.closest('a, button, .dropdown-item');
            if (!el) return;
            if (el.closest('.modal')) return;
            if (el.textContent.trim() !== 'Return to Sales') return;
            if (!window.cur_frm || cur_frm.doc.doctype !== 'Opportunity') return;
            if (!['Pending Costing', 'Costing In Progress'].includes(cur_frm.doc.workflow_state)) return;

            e.preventDefault();
            e.stopPropagation();
            e.stopImmediatePropagation();
            $('.dropdown-menu').removeClass('show');

            const f = cur_frm;
            const d = new frappe.ui.Dialog({
                title: 'Return Inquiry to Sales',
                fields: [{
                    fieldname: 'reason',
                    fieldtype: 'Small Text',
                    label: 'Reason for Return',
                    reqd: 1,
                    description: 'This will be emailed to the sales person.'
                }],
                primary_action_label: 'Return to Sales',
                primary_action(v) {
                    d.get_primary_btn().prop('disabled', true);
                    frappe.call({
                        method: 'savinda_return_inquiry',
                        args: { name: f.doc.name, reason: v.reason },
                        freeze: true,
                        freeze_message: 'Returning inquiry...',
                        callback() {
                            d.hide();
                            frappe.show_alert({
                                message: 'Inquiry returned to sales',
                                indicator: 'orange'
                            });
                            f.reload_doc();
                        },
                        error() { d.get_primary_btn().prop('disabled', false); }
                    });
                }
            });

            d.show();
        }, true);
    }
});

// ============================================================
// GIFT BOX FINISHING CONFIGURATION
// ============================================================

const GIFT_CFG = {
    GIFT_TABLE: "custom_gift_box_types",

    HTML_FIELD: "finishing_checklist_html",
    ROW_KEY_FIELD: "row_key",

    STORE_TABLE: "custom_gift_box_finishings",

    STORE_ROW_REF_FIELD: "page_row_name",
    STORE_FINISHING_FIELD: "finishing",
    STORE_FINISHING_OP_FIELD: "finishing_operation",
    STORE_REMARK_FIELD: "remark",
    STORE_CHECKED_FIELD: "checked"
};


// ============================================================
// OPPORTUNITY EVENTS
// ============================================================

frappe.ui.form.on('Opportunity', {

    refresh(frm) {
        gift_ensure_all_row_keys(frm);
    }

});


// ============================================================
// GIFT BOX TYPES CHILD TABLE EVENTS
// ============================================================

frappe.ui.form.on('Gift Box Types', {

    custom_gift_box_types_add(frm, cdt, cdn) {
        gift_init_row(frm, cdt, cdn);
    },


    form_render: async function(frm, cdt, cdn) {

        gift_init_row(frm, cdt, cdn);

        await gift_render_finishing_checklist(
            frm,
            cdt,
            cdn
        );
    },


    before_custom_gift_box_types_remove(frm, cdt, cdn) {

        const row =
            locals[cdt] &&
            locals[cdt][cdn];


        if (!row) {
            return;
        }


        const row_key =
            row[GIFT_CFG.ROW_KEY_FIELD];


        if (!row_key) {
            return;
        }


        gift_remove_finishings_for_row(
            frm,
            row_key
        );
    }

});


// ============================================================
// CREATE UNIQUE ROW KEY
// ============================================================

function gift_make_row_key() {

    return (
        "gift_" +
        Date.now().toString(36) +
        "_" +
        Math.random()
            .toString(36)
            .slice(2, 10)
    );

}


// ============================================================
// INITIALIZE ONE GIFT BOX ROW
// ============================================================

function gift_init_row(frm, cdt, cdn) {

    const row =
        locals[cdt] &&
        locals[cdt][cdn];


    if (!row) {
        return;
    }


    let changed = false;


    // --------------------------------------------------------
    // Add row key if missing
    // --------------------------------------------------------

    if (!row[GIFT_CFG.ROW_KEY_FIELD]) {

        row[GIFT_CFG.ROW_KEY_FIELD] =
            gift_make_row_key();

        changed = true;
    }


    // --------------------------------------------------------
    // Check whether another Gift Box row has same key
    // --------------------------------------------------------

    const duplicate_exists =
        (
            frm.doc[GIFT_CFG.GIFT_TABLE] || []
        ).some(d => {

            return (
                d.name !== row.name &&
                d[GIFT_CFG.ROW_KEY_FIELD] &&
                d[GIFT_CFG.ROW_KEY_FIELD] ===
                    row[GIFT_CFG.ROW_KEY_FIELD]
            );

        });


    // --------------------------------------------------------
    // If duplicated row, create new key
    // --------------------------------------------------------

    if (duplicate_exists) {

        row[GIFT_CFG.ROW_KEY_FIELD] =
            gift_make_row_key();

        changed = true;
    }


    if (changed) {
        frm.dirty();
    }

}


// ============================================================
// ENSURE ALL GIFT BOX ROWS HAVE UNIQUE KEYS
// ============================================================

function gift_ensure_all_row_keys(frm) {

    const seen = new Set();

    let changed = false;


    (
        frm.doc[GIFT_CFG.GIFT_TABLE] || []
    ).forEach(row => {

        const existing_key =
            row[GIFT_CFG.ROW_KEY_FIELD];


        if (
            !existing_key ||
            seen.has(existing_key)
        ) {

            row[GIFT_CFG.ROW_KEY_FIELD] =
                gift_make_row_key();

            changed = true;
        }


        seen.add(
            row[GIFT_CFG.ROW_KEY_FIELD]
        );

    });


    if (changed) {

        frm.refresh_field(
            GIFT_CFG.GIFT_TABLE
        );

        frm.dirty();
    }

}


// ============================================================
// RENDER FINISHING CHECKLIST
// ============================================================

async function gift_render_finishing_checklist(
    frm,
    cdt,
    cdn
) {

    const row =
        locals[cdt] &&
        locals[cdt][cdn];


    if (!row) {
        return;
    }


    // Make sure row has key
    gift_init_row(
        frm,
        cdt,
        cdn
    );


    const row_key =
        row[GIFT_CFG.ROW_KEY_FIELD];


    // --------------------------------------------------------
    // Find the opened Gift Box child row
    // --------------------------------------------------------

    const grid_row =
        frm
            .fields_dict[
                GIFT_CFG.GIFT_TABLE
            ]
            ?.grid
            ?.grid_rows_by_docname
            ?.[cdn];


    // --------------------------------------------------------
    // Find HTML field inside child row
    // --------------------------------------------------------

    const html_field =
        grid_row
            ?.grid_form
            ?.fields_dict
            ?.[GIFT_CFG.HTML_FIELD];


    if (
        !html_field ||
        !html_field.wrapper
    ) {
        return;
    }


    const $wrapper =
        $(html_field.wrapper);


    // --------------------------------------------------------
    // Loading message
    // --------------------------------------------------------

    $wrapper.html(`
        <div class="text-muted small">
            Loading finishings...
        </div>
    `);


    try {

        // ====================================================
        // LOAD FINISHING MASTER
        // ====================================================

        const finishings =
            await frappe.db.get_list(
                "Finishing",
                {

                    filters: {
                        disabled: 0
                    },

                    fields: [
                        "name",
                        "finishing_operation",
                        "remark"
                    ],

                    order_by:
                        "finishing_operation asc",

                    limit: 500
                }
            );


        // ====================================================
        // GET SAVED FINISHINGS FOR THIS GIFT BOX
        // ====================================================

        const selected_set =
            new Set(

                (
                    frm.doc[
                        GIFT_CFG.STORE_TABLE
                    ] || []
                )

                    .filter(d => {

                        return (
                            d[
                                GIFT_CFG
                                    .STORE_ROW_REF_FIELD
                            ] === row_key
                        );

                    })

                    .map(d => {

                        return d[
                            GIFT_CFG
                                .STORE_FINISHING_FIELD
                        ];

                    })

            );


        // ====================================================
        // NO FINISHING MASTER RECORDS
        // ====================================================

        if (!finishings.length) {

            $wrapper.html(`
                <div class="text-muted small">
                    No active finishing records found.
                </div>
            `);

            return;
        }


        // ====================================================
        // PUT CHECKED FINISHINGS FIRST
        // ====================================================

        const sorted_finishings =
            [...finishings].sort(
                (a, b) => {

                    const a_checked =
                        selected_set.has(a.name)
                            ? 0
                            : 1;


                    const b_checked =
                        selected_set.has(b.name)
                            ? 0
                            : 1;


                    return (
                        a_checked -
                        b_checked
                    );

                }
            );


        // ====================================================
        // BUILD CHECKBOX ITEMS
        // ====================================================

        const items =
            sorted_finishings
                .map(f => {

                    const checked =
                        selected_set.has(f.name)
                            ? "checked"
                            : "";


                    const title =
                        gift_escape_html(
                            f.finishing_operation ||
                            f.name
                        );


                    const remark =
                        f.remark
                            ? `
                                <div class="gift-box-finishing-remark">
                                    ${gift_escape_html(
                                        f.remark
                                    )}
                                </div>
                            `
                            : "";


                    const search_text =
                        (
                            (
                                f.finishing_operation ||
                                f.name ||
                                ""
                            )
                            +
                            " "
                            +
                            (
                                f.remark ||
                                ""
                            )
                        ).toLowerCase();


                    return `
                        <label
                            class="gift-box-finishing-item"
                            data-search="${gift_escape_attr(
                                search_text
                            )}"
                        >

                            <input
                                type="checkbox"
                                class="gift-box-finishing-checkbox"
                                value="${gift_escape_attr(
                                    f.name
                                )}"
                                ${checked}
                            >

                            <div class="gift-box-finishing-content">

                                <div class="gift-box-finishing-title">
                                    ${title}
                                </div>

                                ${remark}

                            </div>

                        </label>
                    `;

                })
                .join("");


        // ====================================================
        // RENDER CHECKLIST
        // ====================================================

        $wrapper.html(`
            <style>

                .gift-box-finishing-wrap {
                    width: 100%;
                }

                .gift-box-finishing-toolbar {
                    margin-bottom: 12px;
                }

                .gift-box-finishing-search {
                    width: 100%;
                    min-height: 36px;
                    border-radius: 8px;
                    padding: 8px 12px;
                    border: 1px solid rgba(255, 255, 255, 0.08);
                    background: rgba(255, 255, 255, 0.02);
                    color: inherit;
                    outline: none;
                }

                .gift-box-finishing-search:focus {
                    border-color: rgba(255, 255, 255, 0.18);
                }

                .gift-box-finishing-search-empty {
                    display: none;
                    padding: 10px 2px 4px;
                    opacity: 0.75;
                    font-size: 12px;
                }

                .gift-box-finishing-grid {
                    display: grid;
                    grid-template-columns: 1fr;
                    gap: 10px 16px;
                    align-items: start;
                }

                @media (min-width: 768px) {

                    .gift-box-finishing-grid {
                        grid-template-columns:
                            repeat(
                                2,
                                minmax(0, 1fr)
                            );
                    }

                }

                @media (min-width: 1200px) {

                    .gift-box-finishing-grid {
                        grid-template-columns:
                            repeat(
                                3,
                                minmax(0, 1fr)
                            );
                    }

                }

                @media (min-width: 1500px) {

                    .gift-box-finishing-grid {
                        grid-template-columns:
                            repeat(
                                4,
                                minmax(0, 1fr)
                            );
                    }

                }

                .gift-box-finishing-item {
                    display: grid;
                    grid-template-columns:
                        18px minmax(0, 1fr);
                    gap: 10px;
                    align-items: start;
                    padding: 8px 10px;
                    margin: 0;
                    border-radius: 8px;
                    cursor: pointer;
                }

                .gift-box-finishing-item:hover {
                    background:
                        rgba(255, 255, 255, 0.03);
                }

                .gift-box-finishing-item
                input[type="checkbox"] {
                    margin-top: 3px;
                }

                .gift-box-finishing-content {
                    min-width: 0;
                }

                .gift-box-finishing-title {
                    font-weight: 500;
                    line-height: 1.35;
                    word-break: break-word;
                }

                .gift-box-finishing-remark {
                    margin-top: 4px;
                    font-size: 12px;
                    opacity: 0.75;
                    line-height: 1.35;
                    word-break: break-word;
                }

            </style>


            <div class="gift-box-finishing-wrap">

                <div class="gift-box-finishing-toolbar">

                    <input
                        type="text"
                        class="gift-box-finishing-search"
                        placeholder="Search finishing..."
                        autocomplete="off"
                    >

                </div>


                <div class="gift-box-finishing-grid">
                    ${items}
                </div>


                <div class="gift-box-finishing-search-empty">
                    No matching finishing found.
                </div>

            </div>
        `);


        // ====================================================
        // REMOVE ONLY EVENTS CREATED BY THIS SCRIPT
        // ====================================================

        $wrapper.off(
            ".giftBoxFinishing"
        );


        // ====================================================
        // CHECKBOX CHANGE
        // ====================================================

        $wrapper.on(
            "change.giftBoxFinishing",
            ".gift-box-finishing-checkbox",
            function() {

                const values =
                    $wrapper
                        .find(
                            ".gift-box-finishing-checkbox:checked"
                        )
                        .map(
                            (i, el) =>
                                el.value
                        )
                        .get();


                gift_sync_store_for_row(
                    frm,
                    row_key,
                    values,
                    finishings
                );


                frm.dirty();

            }
        );


        // ====================================================
        // SEARCH
        // ====================================================

        $wrapper.on(
            "input.giftBoxFinishing",
            ".gift-box-finishing-search",
            function() {

                const query =
                    (
                        $(this).val() ||
                        ""
                    )
                        .toString()
                        .trim()
                        .toLowerCase();


                let visible_count = 0;


                $wrapper
                    .find(
                        ".gift-box-finishing-item"
                    )
                    .each(function() {

                        const text =
                            (
                                $(this).attr(
                                    "data-search"
                                ) ||
                                ""
                            )
                                .toLowerCase();


                        const matched =
                            !query ||
                            text.includes(
                                query
                            );


                        $(this).toggle(
                            matched
                        );


                        if (matched) {
                            visible_count++;
                        }

                    });


                $wrapper
                    .find(
                        ".gift-box-finishing-search-empty"
                    )
                    .toggle(
                        visible_count === 0
                    );

            }
        );


    } catch (error) {

        console.error(
            "Gift Box finishing error:",
            error
        );


        $wrapper.html(`
            <div class="text-danger small">
                Could not load finishing records.
            </div>
        `);

    }

}


// ============================================================
// SYNC FINISHINGS FOR ONE GIFT BOX ROW
// ============================================================

function gift_sync_store_for_row(
    frm,
    row_key,
    selected_values,
    finishings
) {

    const selected =
        new Set(selected_values);


    // --------------------------------------------------------
    // Preserve records belonging to OTHER Gift Box rows
    // --------------------------------------------------------

    const keepers =
        (
            frm.doc[
                GIFT_CFG.STORE_TABLE
            ] || []
        )

            .filter(d => {

                return (
                    d[
                        GIFT_CFG
                            .STORE_ROW_REF_FIELD
                    ] !== row_key
                );

            })

            .map(d => {

                return {

                    row_ref:
                        d[
                            GIFT_CFG
                                .STORE_ROW_REF_FIELD
                        ],

                    finishing:
                        d[
                            GIFT_CFG
                                .STORE_FINISHING_FIELD
                        ],

                    operation:
                        d[
                            GIFT_CFG
                                .STORE_FINISHING_OP_FIELD
                        ] || "",

                    remark:
                        d[
                            GIFT_CFG
                                .STORE_REMARK_FIELD
                        ] || "",

                    checked:
                        d[
                            GIFT_CFG
                                .STORE_CHECKED_FIELD
                        ]
                            ? 1
                            : 0
                };

            });


    // --------------------------------------------------------
    // IMPORTANT:
    // Clears ONLY custom_gift_box_finishings
    // --------------------------------------------------------

    frm.clear_table(
        GIFT_CFG.STORE_TABLE
    );


    // --------------------------------------------------------
    // Restore OTHER Gift Box selections
    // --------------------------------------------------------

    keepers.forEach(d => {

        const child =
            frm.add_child(
                GIFT_CFG.STORE_TABLE
            );


        child[
            GIFT_CFG.STORE_ROW_REF_FIELD
        ] =
            d.row_ref;


        child[
            GIFT_CFG.STORE_FINISHING_FIELD
        ] =
            d.finishing;


        child[
            GIFT_CFG.STORE_FINISHING_OP_FIELD
        ] =
            d.operation;


        child[
            GIFT_CFG.STORE_REMARK_FIELD
        ] =
            d.remark;


        child[
            GIFT_CFG.STORE_CHECKED_FIELD
        ] =
            d.checked;

    });


    // --------------------------------------------------------
    // Add selected finishings for CURRENT Gift Box
    // --------------------------------------------------------

    finishings.forEach(f => {

        if (!selected.has(f.name)) {
            return;
        }


        const child =
            frm.add_child(
                GIFT_CFG.STORE_TABLE
            );


        child[
            GIFT_CFG.STORE_ROW_REF_FIELD
        ] =
            row_key;


        child[
            GIFT_CFG.STORE_FINISHING_FIELD
        ] =
            f.name;


        child[
            GIFT_CFG.STORE_FINISHING_OP_FIELD
        ] =
            f.finishing_operation ||
            f.name;


        child[
            GIFT_CFG.STORE_REMARK_FIELD
        ] =
            f.remark || "";


        child[
            GIFT_CFG.STORE_CHECKED_FIELD
        ] =
            1;

    });


    frm.refresh_field(
        GIFT_CFG.STORE_TABLE
    );

}


