const CFG = {
  PAGE_TABLE: "custom_pages",
  HTML_FIELD: "finishing_checklist_html",
  TEMP_FIELD: "selected_finishings",
  ROW_KEY_FIELD: "row_key",
  STORE_TABLE: "custom_page_finishings",

  STORE_ROW_REF_FIELD: "page_row_name",
  STORE_FINISHING_FIELD: "finishing",
  STORE_FINISHING_OP_FIELD: "finishing_operation",
  STORE_REMARK_FIELD: "remark",
  STORE_CHECKED_FIELD: "checked"
};

frappe.ui.form.on("Opportunity", {
  refresh(frm) {
    ensure_all_row_keys(frm);
  }
});

frappe.ui.form.on("Page Types", {
  custom_pages_add(frm, cdt, cdn) {
    init_page_row(frm, cdt, cdn);
  },

  form_render: async function (frm, cdt, cdn) {
    init_page_row(frm, cdt, cdn);
    await render_finishing_checklist(frm, cdt, cdn);
  },

  before_custom_pages_remove(frm, cdt, cdn) {
    const row = locals[cdt] && locals[cdt][cdn];
    if (!row || !row[CFG.ROW_KEY_FIELD]) return;
    remove_finishings_for_row(frm, row[CFG.ROW_KEY_FIELD]);
  }
});

function make_row_key() {
  return "row_" + Date.now().toString(36) + "_" + Math.random().toString(36).slice(2, 10);
}

function init_page_row(frm, cdt, cdn) {
  const row = locals[cdt] && locals[cdt][cdn];
  if (!row) return;

  let changed = false;

  if (!row[CFG.ROW_KEY_FIELD]) {
    row[CFG.ROW_KEY_FIELD] = make_row_key();
    changed = true;
  }

  if (!row[CFG.TEMP_FIELD]) {
    row[CFG.TEMP_FIELD] = "[]";
    changed = true;
  }

  const duplicate_exists = (frm.doc[CFG.PAGE_TABLE] || []).some(
    d => d.name !== row.name && d[CFG.ROW_KEY_FIELD] && d[CFG.ROW_KEY_FIELD] === row[CFG.ROW_KEY_FIELD]
  );

  if (duplicate_exists) {
    row[CFG.ROW_KEY_FIELD] = make_row_key();
    changed = true;
  }

  if (changed) {
    frm.dirty();
  }
}

function ensure_all_row_keys(frm) {
  const seen = new Set();
  let changed = false;

  (frm.doc[CFG.PAGE_TABLE] || []).forEach(row => {
    if (!row[CFG.ROW_KEY_FIELD] || seen.has(row[CFG.ROW_KEY_FIELD])) {
      row[CFG.ROW_KEY_FIELD] = make_row_key();
      changed = true;
    }
    seen.add(row[CFG.ROW_KEY_FIELD]);

    if (!row[CFG.TEMP_FIELD]) {
      row[CFG.TEMP_FIELD] = "[]";
      changed = true;
    }
  });

  if (changed) {
    frm.refresh_field(CFG.PAGE_TABLE);
    frm.dirty();
  }
}

async function render_finishing_checklist(frm, cdt, cdn) {
  const row = locals[cdt] && locals[cdt][cdn];
  if (!row) return;

  init_page_row(frm, cdt, cdn);

  const row_key = row[CFG.ROW_KEY_FIELD];
  const grid_row = frm.fields_dict[CFG.PAGE_TABLE]?.grid?.grid_rows_by_docname?.[cdn];
  const html_field = grid_row?.grid_form?.fields_dict?.[CFG.HTML_FIELD];

  if (!html_field || !html_field.wrapper) return;

  const $wrapper = $(html_field.wrapper);
  $wrapper.html(`<div class="text-muted small">Loading finishings...</div>`);

  try {
    const finishings = await frappe.db.get_list("Finishing", {
      filters: { disabled: 0 },
      fields: ["name", "finishing_operation", "remark"],
      order_by: "finishing_operation asc",
      limit: 500
    });

    const selected_from_store = new Set(
      (frm.doc[CFG.STORE_TABLE] || [])
        .filter(d => d[CFG.STORE_ROW_REF_FIELD] === row_key)
        .map(d => d[CFG.STORE_FINISHING_FIELD])
    );

    let selected_from_temp = [];
    try {
      selected_from_temp = JSON.parse(row[CFG.TEMP_FIELD] || "[]");
      if (!Array.isArray(selected_from_temp)) selected_from_temp = [];
    } catch (e) {
      selected_from_temp = [];
    }

    const selected_set = new Set([
      ...Array.from(selected_from_store),
      ...selected_from_temp
    ]);

    if (!finishings.length) {
      $wrapper.html(`<div class="text-muted small">No active finishing records found.</div>`);
      return;
    }

    // Sort so checked items appear first, preserving original order within each group
    const sorted_finishings = [...finishings].sort((a, b) => {
      const a_checked = selected_set.has(a.name) ? 0 : 1;
      const b_checked = selected_set.has(b.name) ? 0 : 1;
      return a_checked - b_checked;
    });

    const items = sorted_finishings.map(f => {
      const checked = selected_set.has(f.name) ? "checked" : "";
      const title = escape_html(f.finishing_operation || f.name);
      const remark = f.remark
        ? `<div class="finishing-remark">${escape_html(f.remark)}</div>`
        : "";

      const searchText = `${(f.finishing_operation || f.name || "").toLowerCase()} ${(f.remark || "").toLowerCase()}`;

      return `
        <label class="finishing-item" data-search="${escape_attr(searchText)}">
          <input
            type="checkbox"
            class="finishing-checkbox"
            value="${escape_attr(f.name)}"
            ${checked}
          >
          <div class="finishing-content">
            <div class="finishing-title">${title}</div>
            ${remark}
          </div>
        </label>
      `;
    }).join("");

    $wrapper.html(`
      <style>
        .finishing-checklist-wrap {
          width: 100%;
        }

        .finishing-toolbar {
          margin-bottom: 12px;
        }

        .finishing-search {
          width: 100%;
          min-height: 36px;
          border-radius: 8px;
          padding: 8px 12px;
          border: 1px solid rgba(255, 255, 255, 0.08);
          background: rgba(255, 255, 255, 0.02);
          color: inherit;
          outline: none;
        }

        .finishing-search:focus {
          border-color: rgba(255, 255, 255, 0.18);
        }

        .finishing-search-empty {
          display: none;
          padding: 10px 2px 4px;
          opacity: 0.75;
          font-size: 12px;
        }

        .finishing-grid {
          display: grid;
          grid-template-columns: 1fr;
          gap: 10px 16px;
          align-items: start;
        }

        @media (min-width: 768px) {
          .finishing-grid {
            grid-template-columns: repeat(2, minmax(0, 1fr));
          }
        }

        @media (min-width: 1200px) {
          .finishing-grid {
            grid-template-columns: repeat(3, minmax(0, 1fr));
          }
        }

        @media (min-width: 1500px) {
          .finishing-grid {
            grid-template-columns: repeat(4, minmax(0, 1fr));
          }
        }

        .finishing-item {
          display: grid;
          grid-template-columns: 18px minmax(0, 1fr);
          gap: 10px;
          align-items: start;
          padding: 8px 10px;
          margin: 0;
          border-radius: 8px;
          cursor: pointer;
        }

        .finishing-item:hover {
          background: rgba(255, 255, 255, 0.03);
        }

        .finishing-item input[type="checkbox"] {
          margin-top: 3px;
        }

        .finishing-content {
          min-width: 0;
        }

        .finishing-title {
          font-weight: 500;
          line-height: 1.35;
          word-break: break-word;
        }

        .finishing-remark {
          margin-top: 4px;
          font-size: 12px;
          opacity: 0.75;
          line-height: 1.35;
          word-break: break-word;
        }
      </style>

      <div class="finishing-checklist-wrap">
        <div class="finishing-toolbar">
          <input
            type="text"
            class="finishing-search"
            placeholder="Search finishing..."
            autocomplete="off"
          >
        </div>

        <div class="finishing-grid">
          ${items}
        </div>

        <div class="finishing-search-empty">No matching finishing found.</div>
      </div>
    `);

    $wrapper.off("change.finishing");
    $wrapper.off("input.finishingSearch");

    $wrapper.on("change.finishing", ".finishing-checkbox", function () {
      const values = $wrapper.find(".finishing-checkbox:checked")
        .map((i, el) => el.value)
        .get();

      const current_row = locals[cdt] && locals[cdt][cdn];
      if (current_row) {
        current_row[CFG.TEMP_FIELD] = JSON.stringify(values);
      }

      sync_store_for_row(frm, row_key, values, finishings);
      frm.dirty();
    });

    $wrapper.on("input.finishingSearch", ".finishing-search", function () {
      const query = ($(this).val() || "").toString().trim().toLowerCase();
      let visibleCount = 0;

      $wrapper.find(".finishing-item").each(function () {
        const text = ($(this).attr("data-search") || "").toLowerCase();
        const matched = !query || text.includes(query);
        $(this).toggle(matched);
        if (matched) visibleCount++;
      });

      $wrapper.find(".finishing-search-empty").toggle(visibleCount === 0);
    });

  } catch (e) {
    console.error(e);
    $wrapper.html(`<div class="text-danger small">Could not load finishing records.</div>`);
  }
}

function sync_store_for_row(frm, row_key, selected_values, finishings) {
  const selected = new Set(selected_values);

  const keepers = (frm.doc[CFG.STORE_TABLE] || []).filter(
    d => d[CFG.STORE_ROW_REF_FIELD] !== row_key
  );

  frm.clear_table(CFG.STORE_TABLE);

  keepers.forEach(d => {
    const child = frm.add_child(CFG.STORE_TABLE);
    child[CFG.STORE_ROW_REF_FIELD] = d[CFG.STORE_ROW_REF_FIELD];
    child[CFG.STORE_FINISHING_FIELD] = d[CFG.STORE_FINISHING_FIELD];
    child[CFG.STORE_FINISHING_OP_FIELD] = d[CFG.STORE_FINISHING_OP_FIELD] || "";
    child[CFG.STORE_REMARK_FIELD] = d[CFG.STORE_REMARK_FIELD] || "";
    child[CFG.STORE_CHECKED_FIELD] = d[CFG.STORE_CHECKED_FIELD] ? 1 : 0;
  });

  finishings.forEach(f => {
    if (!selected.has(f.name)) return;

    const child = frm.add_child(CFG.STORE_TABLE);
    child[CFG.STORE_ROW_REF_FIELD] = row_key;
    child[CFG.STORE_FINISHING_FIELD] = f.name;
    child[CFG.STORE_FINISHING_OP_FIELD] = f.finishing_operation || f.name;
    child[CFG.STORE_REMARK_FIELD] = f.remark || "";
    child[CFG.STORE_CHECKED_FIELD] = 1;
  });

  frm.refresh_field(CFG.STORE_TABLE);
}

function remove_finishings_for_row(frm, row_key) {
  const keepers = (frm.doc[CFG.STORE_TABLE] || []).filter(
    d => d[CFG.STORE_ROW_REF_FIELD] !== row_key
  );

  frm.clear_table(CFG.STORE_TABLE);

  keepers.forEach(d => {
    const child = frm.add_child(CFG.STORE_TABLE);
    child[CFG.STORE_ROW_REF_FIELD] = d[CFG.STORE_ROW_REF_FIELD];
    child[CFG.STORE_FINISHING_FIELD] = d[CFG.STORE_FINISHING_FIELD];
    child[CFG.STORE_FINISHING_OP_FIELD] = d[CFG.STORE_FINISHING_OP_FIELD] || "";
    child[CFG.STORE_REMARK_FIELD] = d[CFG.STORE_REMARK_FIELD] || "";
    child[CFG.STORE_CHECKED_FIELD] = d[CFG.STORE_CHECKED_FIELD] ? 1 : 0;
  });

  frm.refresh_field(CFG.STORE_TABLE);
}

function escape_html(value) {
  return String(value || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function escape_attr(value) {
